import {chromium} from 'playwright';import fs from 'node:fs';import {PNG} from 'pngjs';import crypto from 'node:crypto';
const image=fs.readFileSync('tests/fixtures/file-transmission-materials/ORIGINALS/resource_pack/textures/ui/control.png'),src='data:image/png;base64,'+image.toString('base64');
const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:800,height:600},deviceScaleFactor:1});const alphas=[0,.25,.5,.75,.8,1],backgrounds=[[0,0,0],[32,48,64],[255,255,255]];let cases=[];
for(const background of backgrounds)for(const alpha of alphas)for(const kind of ['original-image-opacity','solid-opacity','solid-rgba'])cases.push({background,alpha,kind});
await page.setContent('<style>body{margin:0}#grid{display:grid;grid-template-columns:repeat(12,32px)}.cell{position:relative;width:32px;height:32px}.source{position:absolute;inset:0;width:32px;height:32px}</style><div id="grid">'+cases.map((c,i)=>'<div class="cell" id="c'+i+'" style="background:rgb('+c.background.join(',')+')">'+(c.kind==='original-image-opacity'?'<img class="source" src="'+src+'" style="opacity:'+c.alpha+'">':'<div class="source" style="background:'+(c.kind==='solid-rgba'?'rgba(9,9,9,'+c.alpha+')':'rgb(9,9,9);opacity:'+c.alpha)+'"></div>')+'</div>').join('')+'</div>');await page.evaluate(()=>Promise.all([...document.images].map(x=>x.decode())));const actual=PNG.sync.read(await page.screenshot());
for(let i=0;i<cases.length;i++){const c=cases[i],x=(i%12)*32+16,y=Math.floor(i/12)*32+16,at=(y*actual.width+x)*4;c.actualRGBA=Array.from(actual.data.subarray(at,at+4));c.straightRoundRGBA=[...c.background.map(v=>Math.round(9*c.alpha+v*(1-c.alpha))),255];}
const canvas=await page.evaluate(async src=>{const img=new Image();img.src=src;await img.decode();const canvas=document.createElement('canvas');canvas.width=2;canvas.height=2;const ctx=canvas.getContext('2d');ctx.fillStyle='rgb(32,48,64)';ctx.fillRect(0,0,2,2);ctx.globalAlpha=.8;ctx.drawImage(img,0,0);return Array.from(ctx.getImageData(0,0,1,1).data);},src);
const result={scope:'Independent scalar alpha experiment; no product CSS, planner, window PNG or expected material image used',browser:browser.version(),sourceSHA256:crypto.createHash('sha256').update(image).digest('hex'),cases,canvas2dGlobalAlphaPoint8:canvas};fs.writeFileSync('.cache/file-transmission-browser-01/ALPHA-EXPERIMENT.json',JSON.stringify(result,null,2));console.log(JSON.stringify(cases.filter(x=>x.alpha===.8)));console.log({canvas});}finally{await browser.close();}
